From 1bf20fcdb300d6102916510049fab584b07efb0e Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 21:31:05 +0100
Subject: [PATCH] wallpapers/slideshow: allow previewing a slide on the desktop

In Slideshow mode there was no way to see how a single image looks with
the slideshow's positioning without switching to Image mode. Each slide
now has a Preview button that shows it on the desktop until Apply/Close.

BUG: 476909
---
 .../image/imagepackage/contents/ui/WallpaperDelegate.qml | 9 +++++++++
 wallpapers/image/imagepackage/contents/ui/config.qml     | 4 ++++
 wallpapers/image/imagepackage/contents/ui/main.qml       | 6 +++---
 .../image/slideshowpackage/contents/config/main.xml      | 4 ++++
 4 files changed, 20 insertions(+), 3 deletions(-)

diff --git a/wallpapers/image/imagepackage/contents/ui/WallpaperDelegate.qml b/wallpapers/image/imagepackage/contents/ui/WallpaperDelegate.qml
index f52a8eac58..0182358a0a 100644
--- a/wallpapers/image/imagepackage/contents/ui/WallpaperDelegate.qml
+++ b/wallpapers/image/imagepackage/contents/ui/WallpaperDelegate.qml
@@ -28,6 +28,15 @@ KCM.GridDelegate {
     hoverEnabled: true

     actions: [
+        Kirigami.Action {
+            icon.name: "view-preview"
+            tooltip: i18nd("plasma_wallpaper_org.kde.image", "Preview on Desktop")
+            visible: configDialog.currentWallpaper === "org.kde.slideshow"
+            onTriggered: {
+                root.previewSlide(key, selectors);
+                wallpapersGrid.view.currentIndex = index;
+            }
+        },
         Kirigami.Action {
             icon.name: "document-open-folder"
             tooltip: i18nd("plasma_wallpaper_org.kde.image", "Open Containing Folder")
diff --git a/wallpapers/image/imagepackage/contents/ui/config.qml b/wallpapers/image/imagepackage/contents/ui/config.qml
index 533cc1fff8..4cbca4c4f5 100644
--- a/wallpapers/image/imagepackage/contents/ui/config.qml
+++ b/wallpapers/image/imagepackage/contents/ui/config.qml
@@ -82,6 +82,10 @@ ColumnLayout {
         wallpaperConfiguration.PreviewImage = cfg_Image;
     }

+    function previewSlide(wallpaper: string, selectors: list<string>): void {
+        wallpaperConfiguration.PreviewImage = imageWallpaper.makeWallpaperUrl(wallpaper, selectors).toString();
+    }
+
     function selectDynamicMode(mode: /*PlasmaWallpaper.DynamicMode*/ int): void {
         cfg_DynamicMode = mode;

diff --git a/wallpapers/image/imagepackage/contents/ui/main.qml b/wallpapers/image/imagepackage/contents/ui/main.qml
index 14aac831f8..af371b87b9 100644
--- a/wallpapers/image/imagepackage/contents/ui/main.qml
+++ b/wallpapers/image/imagepackage/contents/ui/main.qml
@@ -69,12 +69,12 @@ WallpaperItem {
         forceImageAnimation: root.configuration.ForceImageAnimation

         source: {
-            if (root.pluginName === "org.kde.slideshow") {
-                return imageWallpaper.image;
-            }
             if (root.configuration.PreviewImage !== "null") {
                 return root.configuration.PreviewImage;
             }
+            if (root.pluginName === "org.kde.slideshow") {
+                return imageWallpaper.image;
+            }
             return root.configuration.Image;
         }
         sourceSize: Qt.size(root.width * Screen.devicePixelRatio, root.height * Screen.devicePixelRatio)
diff --git a/wallpapers/image/slideshowpackage/contents/config/main.xml b/wallpapers/image/slideshowpackage/contents/config/main.xml
index daa132cc9e..e8ef5edc43 100644
--- a/wallpapers/image/slideshowpackage/contents/config/main.xml
+++ b/wallpapers/image/slideshowpackage/contents/config/main.xml
@@ -18,6 +18,10 @@
       <label>Wallpaper image path or wallpaper name</label>
       <default></default>
     </entry>
+    <entry name="PreviewImage" type="String">
+      <label>Wallpaper preview image path</label>
+      <default>null</default>
+    </entry>
     <entry name="FillMode" type="int">
       <label>Sizing, cropping and positioning of the wallpaper image</label>
       <default>2</default>
-- 
2.53.0
